809	    <!-- Section 5: Script -->
810	    <section id="script">
811	        <h2><span class="num">05</span> Workflow 脚本结构</h2>
812	
813	        <p>Workflow 脚本是 <strong>JavaScript</strong> 代码，由 Claude 根据你的任务描述动态编写。脚本本身没有文件系统或 Shell 访问权限——它协调 Agent，Agent 负责实际的读写和命令执行。</p>
814	
815	        <div class="card">
816	            <div class="card-title">📝 脚本示例：深度研究</div>
817	            <div class="script-block">
818	<pre><code><span class="comment">// 深度研究 Workflow</span>
819	<span class="keyword">export const</span> meta = {
820	  name: <span class="string">'deep-research'</span>,
821	  description: <span class="string">'多角度搜索、交叉验证、生成研报'</span>,
822	  phases: [
823	    { title: <span class="string">'搜索'</span>, detail: <span class="string">'扇出 5 个搜索 Agent'</span> },
824	    { title: <span class="string">'验证'</span>, detail: <span class="string">'对抗性验证每个声明'</span> },
825	    { title: <span class="string">'合成'</span>, detail: <span class="string">'合并生成最终报告'</span> }
826	  ]
827	}
828	
829	<span class="comment">// Phase 1: 扇出搜索</span>
830	<span class="keyword">const</span> angles = [<span class="string">'功能特性'</span>, <span class="string">'使用方法'</span>, <span class="string">'竞品对比'</span>, <span class="string">'最佳实践'</span>, <span class="string">'限制'</span>]
831	<span class="keyword">const</span> results = <span class="keyword">await</span> <span class="func">parallel</span>(
832	  angles.map(a => () => <span class="func">agent</span>(<span class="string">`搜索 ${a}`</span>))
833	)
834	
835	<span class="comment">// Phase 2: 对抗性验证</span>
836	<span class="keyword">const</span> verified = <span class="keyword">await</span> <span class="func">parallel</span>(
837	  results.map(r => () =>
838	    <span class="func">agent</span>(<span class="string">`验证: ${r.claim}`</span>, { schema: VERDICT })
839	  )
840	)
841	
842	<span class="comment">// Phase 3: 合成报告</span>
843	<span class="keyword">return</span> verified.filter(v => v.valid)
844	</code></pre>
845	            </div>
846	        </div>
